-- =====================================================================================
-- V81 — Expense categories in the style of ELSTER / DATEV, their rules and the folder they file into.
--
-- Why this is a table and not an enum: the catalogue is a working aid, not a law. A Handwerk business
-- changes its chart, a tax adviser wants another account, a new trade adds a category. Every one of
-- those was a release before; now it is a row.
--
-- Why DATEV accounts are only starting values: SKR03 and SKR04 are published by DATEV and a client's
-- chart can differ from the standard edition. The columns are deliberately nullable and the seed uses
-- the standard base accounts; an administrator corrects them for the client. They are not tax advice.
--
-- Parent rows are shared platform vocabulary (like document_types); the rules are seeded platform-wide
-- and can be extended by an administrator through /api/v1/expense-categories. A rule with a low weight
-- supports a decision, a sender rule identifies a shop; the engine combines the weights, so one weak
-- keyword can never file a document on its own.
-- =====================================================================================

-- -------------------------------------------------------------------------------------
-- The catalogue
-- -------------------------------------------------------------------------------------
CREATE TABLE expense_categories (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code                varchar(120) NOT NULL UNIQUE,
    parent_id           uuid REFERENCES expense_categories (id) ON DELETE RESTRICT,
    name                jsonb NOT NULL,
    description         jsonb NOT NULL DEFAULT '{}'::jsonb,
    -- DATEV base accounts of the standard charts (SKR03 process-oriented, SKR04 balance-sheet-oriented).
    datev_skr03         varchar(10),
    datev_skr04         varchar(10),
    -- Folder template; {year} and {month} are resolved from the document date when a document is filed.
    folder_path         varchar(400),
    sort_order          integer NOT NULL DEFAULT 100,
    is_active           boolean NOT NULL DEFAULT true,
    -- false for Privatentnahme: such a receipt is not a business expense and must not be booked as one.
    is_business_expense boolean NOT NULL DEFAULT true,
    -- true when an automatic decision must be shown to a person with a warning.
    requires_review     boolean NOT NULL DEFAULT false,
    warning             jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT expense_categories_code_chk CHECK (code ~ '^[a-z0-9]+([._-][a-z0-9]+)*$'),
    CONSTRAINT expense_categories_not_own_parent_chk CHECK (parent_id IS NULL OR parent_id <> id)
);

CREATE INDEX expense_categories_parent_idx ON expense_categories (parent_id);
CREATE INDEX expense_categories_active_idx ON expense_categories (is_active, sort_order);

CREATE TRIGGER expense_categories_set_updated_at BEFORE UPDATE ON expense_categories
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE expense_categories IS
    'Extensible catalogue of business expense categories (ELSTER/DATEV style) with localized names, '
    'DATEV base accounts and the archive folder a document is filed into.';
COMMENT ON COLUMN expense_categories.folder_path IS
    'Folder template below the archive root, e.g. /Belege/{year}/Material/Waren. {year} and {month} '
    'are resolved from the document date when the document is categorised.';

-- -------------------------------------------------------------------------------------
-- The rules that recognise a category
-- -------------------------------------------------------------------------------------
CREATE TABLE expense_category_rules (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    category_id   uuid NOT NULL REFERENCES expense_categories (id) ON DELETE CASCADE,
    rule_type     varchar(30) NOT NULL,
    -- Keyword, sender or file-name pattern; empty for amount rules.
    pattern       text,
    amount_min    numeric(12, 2),
    amount_max    numeric(12, 2),
    -- Contribution of one rule to the category score; the engine combines them with 1 - product(1 - w).
    weight        numeric(4, 3) NOT NULL,
    -- Higher priority wins a tie between equally strong categories.
    priority      integer NOT NULL DEFAULT 100,
    -- Terms that must all appear in the text for the rule to count (json array of strings).
    requires_all  jsonb NOT NULL DEFAULT '[]'::jsonb,
    description   jsonb NOT NULL DEFAULT '{}'::jsonb,
    is_active     boolean NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT expense_category_rules_type_chk CHECK (rule_type IN (
        'KEYWORD', 'REGEX', 'SENDER', 'FILENAME', 'AMOUNT_AT_LEAST', 'AMOUNT_AT_MOST', 'AMOUNT_BETWEEN')),
    CONSTRAINT expense_category_rules_weight_chk CHECK (weight > 0 AND weight <= 1),
    CONSTRAINT expense_category_rules_pattern_chk CHECK (
        rule_type IN ('AMOUNT_AT_LEAST', 'AMOUNT_AT_MOST', 'AMOUNT_BETWEEN')
        OR (pattern IS NOT NULL AND length(btrim(pattern)) >= 2)),
    CONSTRAINT expense_category_rules_amount_chk CHECK (
        rule_type NOT IN ('AMOUNT_AT_LEAST', 'AMOUNT_AT_MOST', 'AMOUNT_BETWEEN')
        OR amount_min IS NOT NULL OR amount_max IS NOT NULL),
    CONSTRAINT expense_category_rules_requires_all_chk CHECK (jsonb_typeof(requires_all) = 'array')
);

CREATE INDEX expense_category_rules_category_idx ON expense_category_rules (category_id) WHERE is_active;
CREATE INDEX expense_category_rules_type_idx ON expense_category_rules (rule_type) WHERE is_active;

CREATE TRIGGER expense_category_rules_set_updated_at BEFORE UPDATE ON expense_category_rules
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE expense_category_rules IS
    'Rules that assign an expense category: keywords (German and Russian synonyms), senders, file names '
    'and amount thresholds. Platform-wide and extensible without a release.';

-- -------------------------------------------------------------------------------------
-- The filing result on the document
-- -------------------------------------------------------------------------------------
ALTER TABLE documents
    ADD COLUMN expense_category_id  uuid REFERENCES expense_categories (id) ON DELETE SET NULL,
    ADD COLUMN folder_path          varchar(400),
    ADD COLUMN expense_category_confidence numeric(5, 4),
    -- RULE: the engine decided; MANUAL: a person chose the category.
    ADD COLUMN expense_category_source varchar(10),
    ADD COLUMN expense_category_rationale text,
    ADD COLUMN categorized_at       timestamptz,
    ADD CONSTRAINT documents_expense_confidence_chk CHECK (
        expense_category_confidence IS NULL
        OR (expense_category_confidence >= 0 AND expense_category_confidence <= 1)),
    ADD CONSTRAINT documents_expense_source_chk CHECK (
        expense_category_source IS NULL OR expense_category_source IN ('RULE', 'MANUAL'));

CREATE INDEX documents_expense_category_idx ON documents (tenant_id, expense_category_id)
    WHERE deleted_at IS NULL;
CREATE INDEX documents_folder_path_idx ON documents (tenant_id, folder_path)
    WHERE deleted_at IS NULL;

COMMENT ON COLUMN documents.expense_category_id IS
    'The expense category chosen by the rule engine or by a person.';
COMMENT ON COLUMN documents.folder_path IS
    'Resolved archive folder, e.g. /Belege/2026/Material/Waren; derived from the category template and the document year.';

