JOIN expense_categories p ON p.code = v.parent_code
ON CONFLICT (code) DO NOTHING;

-- Privatentnahme and everything below it is not a business expense: the same warning applies to all of
-- them, and the UI shows it before anybody books the receipt.
UPDATE expense_categories
SET warning = '{"de":"Privatentnahme ist keine Betriebsausgabe. Der Beleg darf nicht als Betriebsausgabe gebucht werden.","en":"A private withdrawal is not a business expense. Do not post this receipt as one.","ru":"Личное изъятие не является расходом бизнеса. Не проводите этот документ как расход."}'::jsonb,
    is_business_expense = false,
    requires_review = true
WHERE code = 'privatentnahme' OR code LIKE 'privatentnahme.%';

