-- Seed: rules
-- -------------------------------------------------------------------------------------
INSERT INTO expense_category_rules (id, category_id, rule_type, pattern, amount_min, amount_max, weight,
                                    priority, requires_all, description, is_active)
SELECT gen_random_uuid(), c.id, v.rule_type, v.pattern, v.amount_min::numeric, v.amount_max::numeric,
       v.weight::numeric, v.priority::integer, coalesce(v.requires_all::jsonb, '[]'::jsonb),
       v.description, true
